from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import goodwill_credit
from ledgerly.errors import BillingError
from ledgerly.models import Invoice, LineItem

def inv(status="issued", price="50.00"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal(price))],status=status)

# basic
r = goodwill_credit(inv(), Decimal("5.00"), "late")
print("basic", r)
assert r == {"invoice_id":"inv_1","amount":Decimal("5.00"),"reason":"late"}

# non-positive
for a in ["0.00","-1.00"]:
    try: goodwill_credit(inv(), a, "x"); print("FAIL", a)
    except BillingError as e: print("nonpos", a, e.code)

# exceeds total
try: goodwill_credit(inv(), "50.01", "x")
except BillingError as e: print("exceeds", e.code)

# exact total ok
print("exact", goodwill_credit(inv(), "50.00", "x")["amount"])

# non-issued
for s in ("draft","paid","void"):
    try: goodwill_credit(inv(s), "1.00", "x")
    except BillingError as e: print("state", s, e.code)

# approval threshold: 1000.00 ok, 1000.01 requires
big = lambda: Invoice("inv_b","cus",lines=[LineItem("x",1,Decimal("2000.00"))],status="issued")
print("at threshold", goodwill_credit(big(), "1000.00", "x")["amount"])
try: goodwill_credit(big(), "1000.01", "x")
except BillingError as e: print("approval", e.code)
print("approved", goodwill_credit(big(), "1000.01", "x", approved_by="mgr")["amount"])

# idempotency returns original without reapplying
audit.clear()
a = goodwill_credit(inv(), "5.00", "first", idempotency_key="k1")
b = goodwill_credit(inv(), "9.00", "second", idempotency_key="k1")
print("idem", a, b, len(audit.events("goodwill_credit")))
assert a == b and len(audit.events("goodwill_credit")) == 1

# rounding via round_money (banker's: 0.125 -> 0.12)
print("round", goodwill_credit(inv(price="10.00"), "0.125", "x")["amount"])
EOF"}

